/// The struct field names, shared by the planner's field accesses.
pub(crate) const PROBABILITY: &str = "probability";
pub(crate) const CHOICE: &str = "choice";
pub(crate) const SCORE: &str = "score";
const PROBABILITIES: &str = "probabilities";
const CONFIDENCE: &str = "confidence";
const VALUE: &str = "value";
const LABEL: &str = "label";

/// The threshold above which `ai_if` is true: yes is more likely than no.
pub(crate) const IF_THRESHOLD: f64 = 0.5;

fn float(name: &str) -> Field {
    Field::new(name, DataType::Float64, true)
}

fn list_of(fields: Vec<Field>) -> DataType {
    DataType::List(Arc::new(Field::new_list_field(
        DataType::Struct(Fields::from(fields)),
        true,
    )))
}

/// The struct one question's answer has.
fn answer_type(question: &Question) -> DataType {
    let fields = match question {
        Question::Noul { .. } => vec![float(PROBABILITY)],
        Question::Choice { .. } => vec![
            Field::new(CHOICE, DataType::Utf8, true),
            Field::new(
                PROBABILITIES,
                list_of(vec![
                    Field::new(VALUE, DataType::Utf8, true),
                    float(PROBABILITY),
                ]),
                true,
            ),
            float(CONFIDENCE),
        ],
        Question::Score { .. } => vec![
            float(SCORE),
            Field::new(
                PROBABILITIES,
                list_of(vec![
                    Field::new(VALUE, DataType::Int64, true),
                    Field::new(LABEL, DataType::Utf8, true),
                    float(PROBABILITY),
                ]),
                true,
            ),
            float(CONFIDENCE),
        ],
    };
    DataType::Struct(Fields::from(fields))
}

/// The struct `ai_decide` returns for `questions`.
pub(crate) fn decision_type(questions: &BTreeMap<String, Question>) -> DataType {
    DataType::Struct(Fields::from(
        questions
            .iter()
            .map(|(id, question)| Field::new(id, answer_type(question), true))
            .collect::<Vec<_>>(),
    ))
}

    /// The SQL type a typed function returns. `ai_decide`'s struct depends on its
    /// questions, so it has none here.
    pub(crate) fn typed_return(self) -> Option<DataType> {
        match self {
            Self::If => Some(DataType::Boolean),
            Self::Probability | Self::Score => Some(DataType::Float64),
            Self::Classify => Some(DataType::Utf8),
            Self::Decide => None,
        }
    }
}

/// One decision function. All five share a [`Decider`], which holds the model store.
#[derive(Debug)]
pub(crate) struct DecisionUdf {

fn return_type(&self, _arg_types: &[DataType]) -> Result<DataType> {
    if let Some(data_type) = self.kind.typed_return() {
        Ok(data_type)
    } else {
        internal_err!("{} derives its return type from its questions", self.name())
    }
}

fn return_field_from_args(&self, args: ReturnFieldArgs) -> Result<FieldRef> {
    crate::args::check_planning_args(self.kind, args.arg_fields, args.scalar_arguments)?;
    let data_type = if let Some(data_type) = self.kind.typed_return() {
        data_type
    } else {
        let questions = crate::args::questions_from_scalar(
            self.kind,
            args.scalar_arguments.get(1).copied().flatten(),
        )?;
        output::decision_type(&questions)
    };
    Ok(Arc::new(Field::new(self.name(), data_type, true)))
}

/// The questions of an `ai_decide` call: a JSON object of question id to a `noul`,
/// `choice` or `score` question, the same grammar as `TypeSafe`'s API and Databricks'
/// `ai_decide`.
pub(crate) fn parse_questions(kind: Kind, text: &str) -> Result<BTreeMap<String, Question>> {
    let Entries(entries) = serde_json::from_str::<Entries<Question>>(text).map_err(|e| {
        plan_datafusion_err!(
            "{}: `questions` is not a valid questions object: {e}. Each entry needs a `type` of 'noul', 'choice' or 'score', with `instructions` and, for choice and score, `criteria`.",
            kind.name()
        )
    })?;
    if entries.is_empty() {
        return plan_err!(
            "{}: `questions` must contain at least one question.",
            kind.name()
        );
    }
    let mut questions = BTreeMap::new();
    for (id, question) in entries {
        if id.trim().is_empty() {
            return plan_err!("{}: a question id cannot be empty.", kind.name());
        }
        if let Question::Choice { criteria, .. } = &question {
            if criteria.is_empty() || criteria.len() > MAX_CHOICE_OPTIONS {
                return plan_err!(
                    "{}: choice question '{id}' must offer between 1 and {MAX_CHOICE_OPTIONS} options in `criteria`; it offers {}.",
                    kind.name(),
                    criteria.len()
                );
            }
            if criteria.keys().any(|label| label.trim().is_empty()) {
                return plan_err!(
                    "{}: choice question '{id}' has an option with an empty label in `criteria`. Give every option a label.",
                    kind.name()
                );
            }
        }
        if questions.contains_key(&id) {
            return plan_err!(
                "{}: question '{id}' is listed more than once. Give each question its own id.",
                kind.name()
            );
        }
        questions.insert(id, question);
    }
    Ok(questions)
